import os
import re
from typing import Dict, List

# Test verisi - paket bağımlılıkları
test_cases = [
    # (input_deps, expected_output)
    ({}, ["python"]),  # Boş bağımlılık
    {
        "requests": [],
        "flask": ["requests"],
        "django": ["flask", "sqlalchemy"]
    }, ["django", "flask", "requests", "sqlalchemy"]),
    {
        "a": ["b"],
        "b": ["c"],
        "c": ["a"]  # döngü
    },
]

def find_packages(deps: Dict[str, List[str]]) -> List[str]:
    """Paketleri bağımlılık sırasına göre sırala ve döngüyü kontrol et."""

    # Paketleri alfabetik olarak sırala
    sorted_pkts = sorted(deps.keys())

    # Her paket için bağımlılıkları topla (tek seferlik)
    all_deps: Dict[str, List[str]] = {}
    for pkg in sorted_pkts:
        deps_for_pkg = deps.get(pkg, [])
        if not deps_for_pkg:
            continue
        all_deps[pkg] = list(set(deps_for_pkg))  # Tekrarları kaldır

    # Bağımlılık dizilerini topla (her bağımlılık tek seferlik)
    dep_list: List[str] = []
    for pkg in sorted_pkts:
        if pkg not in all_deps:
            continue
        for dep in all_deps[pkg]:
            if dep not in all_deps:  # Bağımlı paket yoksa atla
                continue
            dep_list.append(dep)

    # Döngü kontrolü
    i = 0
    while True:
        pkg = sorted_pkts[i]
        next_pkg = all_deps[pkg]

        if not next_pkg:
            break

        # Sonraki paketin bağımlılıkları
        deps_of_next = all_deps.get(next_pkg, [])

        # Eğer sonraki paketin bağımlılığı içinde mevcut ise döngü var
        for dep in deps_of_next:
            if dep == pkg or dep in dep_list:
                return ValueError("DonguHatasi")

        i += 1

    # Döngü yoksa, alfabetik sıraya göre sırala ve döndür
    return sorted(dep_list)

# Test
for test_idx, (deps, expected) in enumerate(test_cases):
    result = find_packages(deps)
    status = "✓" if result == expected else "✗"
    print(f"{status} Test {test_idx}: {result}")

